-- FA-001 Agent-directed payment to a third party the clearing agreement does not cover
SELECT
  'FA-001' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
WHERE
  (
    a.direction = 'out'
    AND NOT a.directing_agent_id IS NULL
    AND a.in_agent_agreement = 0
  );
